// Get Apollo and SerpAPI outputs safely
const apollo = $node["Apollo API"].json || {};
const serpapi = $node["SerpAPI Jobs"].json || {};

// Extract company information from Apollo API response
const org = apollo.organization || apollo;

// Basic company info
const companyName = org.name || "Unknown Company";
const domain = org.primary_domain || org.website_url || "N/A";
const industry = org.industry || "Not specified";
const revenue = org.organization_revenue_printed || org.annual_revenue_printed || "Unknown";
const employeeCount = org.estimated_num_employees || org.employee_count || "Unknown";
const location = org.raw_address || "Unknown";

// Extract keywords (if available)
const keywords = Array.isArray(org.keywords) ? org.keywords.slice(0, 10) : [];

// Extract tech stack
const techStack = Array.isArray(org.technology_names) ? org.technology_names.slice(0, 10) : [];

// Hiring signal (from SerpAPI jobs)
const hiringSignal = Array.isArray(serpapi.jobs_results) && serpapi.jobs_results.length > 0;

// Simple confidence score formula
let confidence = 0.4; // base weight for firmographic match
if (techStack.length > 0) confidence += 0.3;
if (hiringSignal) confidence += 0.3;

// Build structured final object
return [
  {
    json: {
      company_name: companyName,
      domain: domain,
      industry: industry,
      revenue: revenue,
      employee_count: employeeCount,
      location: location,
      keywords: keywords,
      tech_stack: techStack,
      signals: {
        recent_hiring: hiringSignal
      },
      source: ["Apollo", "SerpAPI"],
      confidence: confidence.toFixed(2)
    }
  }
];
